sqlGroup.select:
select a.id, a.module, a.`recordType`, b.dname as recordTypeName, a.`userId`, d.`nickName` as userName, a.`action`, a.`busiTable`, a.`busiId`, a.ip, a.status, c.dname as statusName, e.dname as recordPointName, a.`execTime`, a.`recordTime`
from sys_log a left join sys_dict b on a.`recordType`=b.dval and b.tcode='LOG_RECORD_TYPE' left join sys_dict c on a.status=c.dval and c.tcode='LOG_RECORD_STATUS' left join sys_user d on d.id=a.`userId` left join sys_dict e on a.`recordPoint`=e.dval and e.tcode='LOG_RECORD_POINT'
and a.busiTable like '%${busiTable}%'
and d.nickName like '%${userName}%'
and a.userId = #{userId}
and a.action = #{action}
and a.status = #{status}
and a.recordTime >= #{startDate}
and a.recordTime <= #{endDate}
order by a.recordTime desc
